// Remove ALL spaces, tabs, newlines, backslashes, etc.
str = str
  .replace(/\s+/g, ' ')      // remove spaces / tabs / newlines
  .replace(/\\+/g, '')      // remove backslashes
  .replace(/\n+/g, '')      // remove line breaks
  .replace(/\r+/g, '');     // remove carriage returns

return [
  {
    json: {
      merged: str
    }
  }
];

